 programs:{title:'Programs',singular:'Program',eyebrow:'PROGRAM CONTROL',desc:'Define scheme/program context before contracts and allocations.',endpoint:'/programs',cols:[['name','Program'],['code','Code'],['scheme','Scheme'],['financialYear','Financial year'],['status','Status']],fields:[['name','Program name'],['code','Program code'],['authority','Authority'],['scheme','Scheme / initiative'],['component','Component'],['financialYear','Financial year'],['sanctionedQuantity','Sanctioned quantity','number'],['contractValue','Expected value','number'],['slaConfig.surveyHours','Survey SLA (hours)','number'],['slaConfig.installationHours','Installation SLA (hours)','number'],['slaConfig.finalInspectionHours','Final inspection SLA (hours)','number'],['status','Status','programStatus']]},
