 'work-orders':{title:'Work Orders',singular:'Work Order',eyebrow:'EXECUTION CONTROL',desc:'Translate awarded work into controlled company work orders.',endpoint:'/work-orders',cols:[['number','Work order'],['title','Title'],['programId.name','Program'],['sanctionedQuantity','Quantity'],['status','Status']],fields:[['programId','Program','program'],['contractId','Contract / LOA','contract'],['number','Work order number'],['title','Title'],['sanctionedQuantity','Sanctioned quantity','number'],['contractValue','Work order value','number'],['status','Status','programStatus']]},
