  <section className="portfolio-level-summary"><div><small>CURRENT VIEW</small><b>{levelTitle}</b><span>{program?`${program.code} · ${program.name}`:'All company delivery records'}</span></div><div><small>RECORDS</small><b>{level==='contracts'?visibleContracts.length+(directWos.length?1:0):(level==='beneficiaries'?beneficiaries.total:(currentRows||[]).length)}</b><span>Matching current search and filters</span></div><div><small>BENEFICIARIES</small><b>{fmt(currentBeneficiaries)}</b><span>Linked to this view</span></div><div><small>ACTIVE / OPEN</small><b>{level==='beneficiaries'?'—':fmt(activeCount)}</b><span>{level==='beneficiaries'?'Use execution status below':'Records still in execution'}</span></div></section>
