 const cfg=resourceConfig[kind],[items,setItems]=useState([]),[edit,setEdit]=useState(null),[selected,setSelected]=useState(null),[refs,setRefs]=useState({programs:[],contracts:[]}),[error,setError]=useState(''),[loading,setLoading]=useState(true),[query,setQuery]=useState(''),[statusFilter,setStatusFilter]=useState(''),[filterOpen,setFilterOpen]=useState(false);
